package agent
import("context";"fmt";"strings")
type CategoryRequest struct{Scope Scope;Category Category;Input string}
type CategoryRuntime interface{Run(context.Context,CategoryRequest)(Response,error)}
type Orchestrator struct{fleet *Fleet;runtimes map[Category]CategoryRuntime}
func NewOrchestrator(fleet *Fleet,runtimes map[Category]CategoryRuntime)(*Orchestrator,error){if fleet==nil{return nil,fmt.Errorf("agent fleet is required")};if len(runtimes)==0{return nil,fmt.Errorf("agent categories are required")};copyMap:=make(map[Category]CategoryRuntime,len(runtimes));for category,runtime:=range runtimes{if strings.TrimSpace(string(category))==""||runtime==nil{continue};copyMap[category]=runtime};if len(copyMap)==0{return nil,fmt.Errorf("agent categories are invalid")};return &Orchestrator{fleet:fleet,runtimes:copyMap},nil}
func(o *Orchestrator)Handle(ctx context.Context,request CategoryRequest)(Response,error){if o==nil{return Response{},fmt.Errorf("agent orchestrator is required")};if ctx==nil{return Response{},fmt.Errorf("context is required")};if err:=ctx.Err();err!=nil{return Response{},err};runtime,ok:=o.runtimes[request.Category];if !ok||runtime==nil{return Response{},fmt.Errorf("unsupported agent category: %s",request.Category)};request.Input=strings.TrimSpace(request.Input);if request.Input==""{return Response{},fmt.Errorf("agent input is required")};return runtime.Run(ctx,request)}
